def drains_to_both(heights: list[list[int]]) -> list[list[int]]:
    rows, cols = len(heights), len(heights[0])

    def climb(edge: list[tuple[int, int]]) -> set[tuple[int, int]]:
        seen, stack = set(edge), list(edge)  # every edge cell of this sea at once
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                inside = 0 <= nr < rows and 0 <= nc < cols
                if inside and (nr, nc) not in seen and heights[nr][nc] >= heights[r][c]:
                    seen.add((nr, nc))           # uphill: its rain can flow down to here
                    stack.append((nr, nc))
        return seen

    sea_a = climb([(0, c) for c in range(cols)] + [(r, 0) for r in range(rows)])
    sea_b = climb([(rows - 1, c) for c in range(cols)] + [(r, cols - 1) for r in range(rows)])
    return [[r, c] for r, c in sea_a & sea_b]

