perf.naive:
def drains_to_both(heights: list[list[int]]) -> list[list[int]]:
    rows, cols = len(heights), len(heights[0])
    both = []
    for sr in range(rows):
        for sc in range(cols):                # follow the rain from each cell on its own
            seen, stack = {(sr, sc)}, [(sr, sc)]
            a = b = False
            while stack and not (a and b):
                r, c = stack.pop()
                a = a or r == 0 or c == 0
                b = b or r == rows - 1 or c == cols - 1
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    inside = 0 <= nr < rows and 0 <= nc < cols
                    if inside and (nr, nc) not in seen and heights[nr][nc] <= heights[r][c]:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if a and b:
                both.append([sr, sc])
    return both
